import { z } from 'zod';

// `code` is auto-generated by the service (LP-0001, LP-0002, ...) unless the
// client supplies one explicitly — same convention as Promotion/GiftVoucher.
// `programName` (not `name`) is the wire/API field name kept
// domain-specific, same as Promotion's `promotionName` — the service's
// toRowData() maps it onto the Prisma column called `name`.
export const createLoyaltyProgramSchema = z
  .object({
    code: z.string().trim().min(1).optional(),
    programName: z.string().trim().min(1, 'Program name is required'),
    description: z.string().trim().max(500).optional().or(z.literal('')).nullable(),
    status: z.enum(['Active', 'Inactive']).default('Active'),
    earnPointsOn: z.enum(['total-bill', 'specific-items', 'specific-category', 'visit'], {
      errorMap: () => ({ message: 'Select how points are earned' }),
    }),
    pointsType: z.enum(['fixed', 'percentage'], {
      errorMap: () => ({ message: 'Select a points type' }),
    }),
    // Coerced to a number here (never trusted as-is from the client) so
    // "10abc" or a negative value can never reach the database — the
    // frontend's own zod schema blocks these at the form too, but the
    // backend is the actual source of truth.
    pointsValue: z.coerce.number().nonnegative('Points value cannot be negative').default(0),
    redemptionType: z.enum(['discount', 'cashback', 'free-item'], {
      errorMap: () => ({ message: 'Select a redemption type' }),
    }),
    redemptionValue: z.coerce.number().nonnegative('Redemption value cannot be negative').default(0),
    minimumPointsRequired: z.coerce.number().int('Minimum points required must be a whole number').nonnegative().default(0),
    maximumDiscountPerTransaction: z.coerce.number().nonnegative('Maximum discount cannot be negative').default(0),
    applyOn: z.enum(['all', 'specific', 'category']).default('all'),
    membershipValidity: z.enum(['lifetime', 'fixed-period'], {
      errorMap: () => ({ message: 'Select membership validity' }),
    }),
    validityPeriodMonths: z.coerce.number().int('Validity period must be a whole number').nonnegative().default(0),
    pointsExpiry: z.enum(['never', '6-months', '12-months', '24-months'], {
      errorMap: () => ({ message: 'Select points expiry' }),
    }),
    welcomePointsEnabled: z.coerce.boolean().default(false),
    welcomePointsValue: z.coerce.number().int('Welcome points must be a whole number').nonnegative().default(0),
    allowPointsRedemption: z.coerce.boolean().default(true),
    showLoyaltyDetailsInInvoice: z.coerce.boolean().default(true),
    allowNegativePoints: z.coerce.boolean().default(false),
    pointsExpiryNotification: z.coerce.boolean().default(true),
  })
  .superRefine((values, ctx) => {
    if (values.membershipValidity === 'fixed-period' && values.validityPeriodMonths <= 0) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['validityPeriodMonths'], message: 'Enter a validity period greater than 0' });
    }
    if (values.welcomePointsEnabled && values.welcomePointsValue <= 0) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['welcomePointsValue'], message: 'Enter a welcome points value greater than 0' });
    }
    if (values.pointsType === 'percentage' && values.pointsValue > 100) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['pointsValue'], message: 'Percentage cannot exceed 100%' });
    }
  });

// Edit mode always resubmits the whole form (see CreateLoyaltyProgramPage),
// so the update schema keeps the same full validation instead of `.partial()`.
export const updateLoyaltyProgramSchema = createLoyaltyProgramSchema;
